package sv.edu.udb.pokebattle.service;
import lombok.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import sv.edu.udb.pokebattle.dto.*; import sv.edu.udb.pokebattle.exception.*; import sv.edu.udb.pokebattle.model.Jugador; import sv.edu.udb.pokebattle.repository.JugadorRepository; import java.util.*;
@Service @RequiredArgsConstructor @Transactional public class JugadorService { private final JugadorRepository repository; public JugadorResponse crear(CrearJugadorRequest d){String n=d.nombre().trim();if(repository.existsByNombreIgnoreCase(n))throw new ConflictoException("El nombre ya está registrado");Jugador j=new Jugador();j.setNombre(n);return JugadorResponse.desde(repository.save(j));} @Transactional(readOnly=true) public List<JugadorResponse> listar(){return repository.findAll().stream().map(JugadorResponse::desde).toList();} @Transactional(readOnly=true) public JugadorResponse obtener(UUID id){return JugadorResponse.desde(buscarEntidad(id));} public Jugador buscarEntidad(UUID id){return repository.findById(id).orElseThrow(()->new RecursoNoEncontradoException("Jugador no encontrado"));} }
